class Item {
    // 상품마다 따로 갖는 가격이에요.
    int price;

    // new Item(값)을 하면 이 생성자가 실행돼요.
    Item(int price) {
        // 받은 가격을 필드에 담으려는 줄이에요.
        price = price;
    }
}

class Main {
    public static void main(String[] args) {
        // 상품을 만들 때 넘길 가격이에요.
        int cost = 4500;
        // 괄호 안 값이 생성자의 price로 들어가요.
        Item pen = new Item(cost);
        // 객체의 price 필드를 출력해요.
        System.out.println("가격: " + pen.price);
    }
}

