class Account {
    // 클래스 밖에서는 못 쓰는 잔액이에요.
    private int balance;

    // 처음 잔액을 받아 필드에 담아요.
    Account(int balance) {
        this.balance = balance;
    }

    // 잔액을 읽어서 돌려줘요.
    int getBalance() {
        return balance;
    }

    // 돌려주는 값이 없어서 void예요.
    void withdraw(int money) {
        // 잔액보다 많이는 못 빼요.
        if (money <= balance) {
            balance -= money;
        }
    }
}

