class QuestContract {
    // The prepared values' output, then each scenario: output, then name/value pairs. Base64 keeps any text intact.
    static final String BASE = "R3Vlc3Qg7IOd7ISx7J6QOiAxCuydvOuwmCAxCkd1ZXN0IOyDneyEseyekDogMgrsnbzrsJggMgpHdWVzdCDsg53shLHsnpA6IDMKVmlwIOyDneyEseyekDogMwpWSVAgMwpHdWVzdCDsg53shLHsnpA6IDQK7J2867CYIDQ=";
